// ThreadServiceClient is a client for the banda.v1.ThreadService service.
type ThreadServiceClient interface {
	CreateThread(context.Context, *v1.CreateThreadRequest) (*v1.CreateThreadResponse, error)
	ListThreads(context.Context, *v1.ListThreadsRequest) (*v1.ListThreadsResponse, error)
	GetThread(context.Context, *v1.GetThreadRequest) (*v1.GetThreadResponse, error)
	SendMessage(context.Context, *v1.SendMessageRequest) (*v1.SendMessageResponse, error)
	Interrupt(context.Context, *v1.InterruptRequest) (*v1.InterruptResponse, error)
	SetMode(context.Context, *v1.SetModeRequest) (*v1.SetModeResponse, error)
	// Changes the agent's model, effort and profile (owner only). A running
	// agent restarts with them once its turns have ended; a paused one starts
	// with them.
	SetAgentSettings(context.Context, *v1.SetAgentSettingsRequest) (*v1.SetAgentSettingsResponse, error)
	Retry(context.Context, *v1.RetryRequest) (*v1.RetryResponse, error)
	// Owner only: runs a teammate's turn request as their turn, or drops it.
	ApproveTurn(context.Context, *v1.ApproveTurnRequest) (*v1.ApproveTurnResponse, error)
	DeclineTurn(context.Context, *v1.DeclineTurnRequest) (*v1.DeclineTurnResponse, error)
	// Owner only: whether teammates can start turns without approval.
	Trust(context.Context, *v1.TrustRequest) (*v1.TrustResponse, error)
	// A sub-thread of parent_id, owned by the caller. It starts from the
	// parent's branch if that was pushed, else from the parent's base branch.
	SpawnThread(context.Context, *v1.SpawnThreadRequest) (*v1.SpawnThreadResponse, error)
	// The sub-threads of a thread, most recently active first.
	LineageChildren(context.Context, *v1.LineageChildrenRequest) (*v1.LineageChildrenResponse, error)
	// Replays stored events with seq > after_seq (or the last `tail`), then
	// streams live events. Large payloads are cut (Event.truncated).
	WatchThread(context.Context, *v1.WatchThreadRequest) (ThreadServiceWatchThreadClientStream, error)
	// Older stored events, for paging back from a tail, or one event in full.
	History(context.Context, *v1.HistoryRequest) (*v1.HistoryResponse, error)
	// Other users' threads in which the caller is mentioned and hasn't answered.
	ListMentioned(context.Context, *v1.ListMentionedRequest) (*v1.ListMentionedResponse, error)
	// Per-viewer snooze; an unset `until` clears it. The owner snoozing also
	// suspends the environment.
	Snooze(context.Context, *v1.SnoozeRequest) (*v1.SnoozeResponse, error)
	// Per-viewer settle. The owner settling also suspends the environment.
	Settle(context.Context, *v1.SettleRequest) (*v1.SettleResponse, error)
	// Pushes the thread branch to origin (owner only). The result arrives as a
	// notice event.
	Push(context.Context, *v1.PushRequest) (*v1.PushResponse, error)
	// Provisions a fresh environment for a thread whose settled environment was
	// deleted, from its pushed branch (owner only).
	EnvironmentRecreate(context.Context, *v1.EnvironmentRecreateRequest) (*v1.EnvironmentRecreateResponse, error)
	// A terminal in the thread's environment (owner only). Output streams until
	// the process exits; opening again replaces the previous terminal.
	OpenTerminal(context.Context, *v1.OpenTerminalRequest) (ThreadServiceOpenTerminalClientStream, error)
	WriteTerminal(context.Context, *v1.WriteTerminalRequest) (*v1.WriteTerminalResponse, error)
	ResizeTerminal(context.Context, *v1.ResizeTerminalRequest) (*v1.ResizeTerminalResponse, error)
	// The tracked and unignored files of the thread's checkout, read from the
	// running environment. Fails while it is not running.
	ListFiles(context.Context, *v1.ListFilesRequest) (*v1.ListFilesResponse, error)
	ReadFile(context.Context, *v1.ReadFileRequest) (*v1.ReadFileResponse, error)
	// The TCP ports listening in the thread's environment (everyone): the
	// current state, then every change. Never wakes a paused environment,
	// except for the owner with `wake` set.
	PreviewWatch(context.Context, *v1.PreviewWatchRequest) (ThreadServicePreviewWatchClientStream, error)
	// A URL on the preview origin that shows what listens on `port`, through
	// the runner. Opening it signs the browser in to the preview origin.
	PreviewOpen(context.Context, *v1.PreviewOpenRequest) (*v1.PreviewOpenResponse, error)
	// The caller's sidebar: sent at once, then again whenever one of its
	// threads changes or the caller is mentioned somewhere new.
	InboxWatch(context.Context, *v1.InboxWatchRequest) (ThreadServiceInboxWatchClientStream, error)
	// Marks the thread read for the caller, up to its latest event.
	InboxMarkRead(context.Context, *v1.InboxMarkReadRequest) (*v1.InboxMarkReadResponse, error)
	// Tells the thread's watchers that the caller is typing. The composer calls
	// it every few seconds while typing; clients forget it after a few seconds.
	SendTyping(context.Context, *v1.TypingRequest) (*v1.TypingResponse, error)
	// Everyone's recent threads that their owners haven't settled, with their
	// last activity and who is looking at them: sent at once, then again
	// (coalesced) whenever one changes.
	TeamWatch(context.Context, *v1.TeamWatchRequest) (ThreadServiceTeamWatchClientStream, error)
	// What happened since the caller last saw the brief (BriefSeen), or in the
	// last day: teammates' finished turns, sub-threads, settled threads, and
	// what waits for the caller now.
	Brief(context.Context, *v1.BriefRequest) (*v1.BriefResponse, error)
	// Marks the brief seen up to its `until`.
	BriefSeen(context.Context, *v1.BriefSeenRequest) (*v1.BriefSeenResponse, error)
	// Answers the agent's pending permission request: the owner, or anyone in
	// a trusted thread. Approving a plan (ExitPlanMode) is for the owner only
	// and switches the thread to `mode`.
	PermissionAnswer(context.Context, *v1.PermissionAnswerRequest) (*v1.PermissionAnswerResponse, error)
	// Sets which tool calls the agent must ask for (owner only). Applies to the
	// running agent at once.
	PermissionSetMode(context.Context, *v1.PermissionSetModeRequest) (*v1.PermissionSetModeResponse, error)
	// Votes for answers to the agent's pending question (AskUserQuestion):
	// anyone, shown on the card for whoever answers. A new vote replaces the
	// caller's last one.
	PermissionVote(context.Context, *v1.PermissionVoteRequest) (*v1.PermissionVoteResponse, error)
	// Removes a tool or rule from the thread's "always allow" list: the owner,
	// or anyone in a trusted thread.
	PermissionRevoke(context.Context, *v1.PermissionRevokeRequest) (*v1.PermissionRevokeResponse, error)
	// Starts threads (one per try) from another thread's current changes and
	// conversation, owned by the caller. Anyone who can see a thread can fork it.
	Fork(context.Context, *v1.ForkRequest) (*v1.ForkResponse, error)
	// Starts sibling threads with the same prompt, one per try.
	Race(context.Context, *v1.RaceRequest) (*v1.RaceResponse, error)
	// Status, cost, time, latest reply and diff of threads, side by side.
	// NotFound when there are none.
	RaceCompare(context.Context, *v1.RaceCompareRequest) (*v1.RaceCompareResponse, error)
	// Everyone's most recent races, newest first: the threads of each, without
	// diffs.
	RaceList(context.Context, *v1.RaceListRequest) (*v1.RaceListResponse, error)
	// Keeps one thread of a race (owner only): settles its siblings for the
	// caller and notes the pick in each.
	RacePick(context.Context, *v1.RacePickRequest) (*v1.RacePickResponse, error)
	// Full-text search over every thread's messages, review comments, agent
	// text and tool calls, best matches first.
	Search(context.Context, *v1.SearchRequest) (*v1.SearchResponse, error)
	// Offers the thread to a teammate (owner only). If the agent is idle, it
	// first writes a briefing for them, as the owner's last turn. The next
	// turns run on the recipient's subscription once they accept.
	HandoffOffer(context.Context, *v1.HandoffOfferRequest) (*v1.HandoffOfferResponse, error)
	// Takes the offered thread (the recipient only): its environment restarts
	// with the recipient's Claude login and secrets, in a new Claude Code
	// session that gets the conversation so far. Refused while the agent works.
	HandoffAccept(context.Context, *v1.HandoffAcceptRequest) (*v1.HandoffAcceptResponse, error)
	// Withdraws the pending offer: declined by the recipient, or cancelled by
	// the owner.
	HandoffDecline(context.Context, *v1.HandoffDeclineRequest) (*v1.HandoffDeclineResponse, error)
	// The thread's pull request (GitLab: merge request) as last fetched from
	// its forge with the owner's token, for everyone; refresh fetches it now.
	PullRequestGet(context.Context, *v1.PullRequestGetRequest) (*v1.PullRequestGetResponse, error)
	// Opens a pull request for the thread's pushed branch against its base
	// (owner only, with the owner's token).
	PullRequestCreate(context.Context, *v1.PullRequestCreateRequest) (*v1.PullRequestCreateResponse, error)
	// Links an existing pull request: by number, or the open one whose head is
	// the thread's branch (owner only).
	PullRequestLink(context.Context, *v1.PullRequestLinkRequest) (*v1.PullRequestLinkResponse, error)
	// Edits the title or description, marks it draft or ready, requests
	// reviewers (owner only).
	PullRequestUpdate(context.Context, *v1.PullRequestUpdateRequest) (*v1.PullRequestUpdateResponse, error)
	// Merges it (owner only).
	PullRequestMerge(context.Context, *v1.PullRequestMergeRequest) (*v1.PullRequestMergeResponse, error)
	// Comments on it, or replies to a review comment, with the caller's own
	// token (refused without one).
	PullRequestComment(context.Context, *v1.PullRequestCommentRequest) (*v1.PullRequestCommentResponse, error)
	// The caller's repositories on the forges they have a token for, for the
	// new-thread composer.
	ListForgeRepos(context.Context, *v1.ListForgeReposRequest) (*v1.ListForgeReposResponse, error)
	// Who may be asked for a review and which labels exist on the thread's
	// repository, from its forge with the owner's token (owner only).
	PullRequestChoices(context.Context, *v1.PullRequestChoicesRequest) (*v1.PullRequestChoicesResponse, error)
	// Resolves or reopens a review thread, with the caller's own token
	// (refused without one).
	PullRequestResolve(context.Context, *v1.PullRequestResolveRequest) (*v1.PullRequestResolveResponse, error)
	// Gives a thread without a repository one (owner only, not while the agent
	// works): the environment restarts with the folder as a checkout of the
	// thread branch, its files kept as uncommitted changes. Until a checkout of
	// it succeeded, the repository can be changed, or removed (empty repo_url).
	AddRepository(context.Context, *v1.AddRepositoryRequest) (*v1.AddRepositoryResponse, error)
	// Gives the thread a title of the owner's choosing.
	RenameThread(context.Context, *v1.RenameThreadRequest) (*v1.RenameThreadResponse, error)
}

